\resizebox{\columnwidth}{!}{%
\begin{tabular}{llccc}
\toprule
\textbf{Error Category} & \textbf{Direction} & \textbf{1.7B} & \textbf{4B} & \textbf{8B / LLaMA} \\
\midrule
